package com.vandorlabs.propulsion;
/** Released float block rotations, centered exactly as Forge TRSR blockCenterToCorner. */
public final class PropulsionModelRotation {
 private static final int[][] CORNERS={{1,0,4,5},{2,3,7,6},{6,4,0,2},{3,1,5,7},{2,0,1,3},{7,5,4,6}};
 private static final float[][] MATRICES=new float[16][],NORMALS=new float[16][];
 static{for(int x=0;x<4;x++)for(int y=0;y<4;y++){float[] plus=identity(),minus=identity();plus[3]=plus[7]=plus[11]=.5F;minus[3]=minus[7]=minus[11]=-.5F;MATRICES[x*4+y]=multiply(multiply(plus,multiply(rotation(1,-y*90),rotation(0,-x*90))),minus);NORMALS[x*4+y]=normal(MATRICES[x*4+y]);}}
 private PropulsionModelRotation(){}
 private static float[] normal(float[] m){double a=m[0],b=m[1],c=m[2],d=m[4],e=m[5],f=m[6],g=m[8],h=m[9],i=m[10];double[] cofactor={e*i-f*h,f*g-d*i,d*h-e*g,c*h-b*i,a*i-c*g,b*g-a*h,b*f-c*e,c*d-a*f,a*e-b*d};double det=a*cofactor[0]+b*cofactor[1]+c*cofactor[2];float[] result=new float[9];for(int n=0;n<9;n++)result[n]=(float)(cofactor[n]/det);return result;}
 public static float normal(int x,int y,int row,float a,float b,float c){float[] m=NORMALS[(Math.floorMod(x,360)/90)*4+Math.floorMod(y,360)/90];return m[row*3]*a+m[row*3+1]*b+m[row*3+2]*c;}
 private static float[] identity(){float[] m=new float[16];for(int i=0;i<4;i++)m[i*4+i]=1;return m;}
 private static float[] rotation(int axis,int angle){float[] m=identity();float radians=angle*.017453292F,c=(float)Math.cos(radians),s=(float)Math.sin(radians);int a=(axis+1)%3,b=(axis+2)%3;m[a*4+a]=m[b*4+b]=c;m[a*4+b]=-s;m[b*4+a]=s;m[axis*4+axis]=(1-c)+c;return m;}
 private static float[] multiply(float[] a,float[] b){float[] r=new float[16];for(int row=0;row<4;row++)for(int col=0;col<4;col++)r[row*4+col]=a[row*4]*b[col]+a[row*4+1]*b[4+col]+a[row*4+2]*b[8+col]+a[row*4+3]*b[12+col];return r;}
 public static float element(int x,int y,int row,int col){return MATRICES[(Math.floorMod(x,360)/90)*4+Math.floorMod(y,360)/90][row*4+col];}
 public static float component(int x,int y,int row,float a,float b,float c,boolean position){float[] m=MATRICES[(Math.floorMod(x,360)/90)*4+Math.floorMod(y,360)/90];return m[row*4]*a+m[row*4+1]*b+m[row*4+2]*c+(position?m[row*4+3]:0);}
 public static int direction(int[] data,int stride){float ax=Float.intBitsToFloat(data[0])-Float.intBitsToFloat(data[stride]),ay=Float.intBitsToFloat(data[1])-Float.intBitsToFloat(data[stride+1]),az=Float.intBitsToFloat(data[2])-Float.intBitsToFloat(data[stride+2]),bx=Float.intBitsToFloat(data[stride*2])-Float.intBitsToFloat(data[stride]),by=Float.intBitsToFloat(data[stride*2+1])-Float.intBitsToFloat(data[stride+1]),bz=Float.intBitsToFloat(data[stride*2+2])-Float.intBitsToFloat(data[stride+2]);float nx=by*az-bz*ay,ny=bz*ax-bx*az,nz=bx*ay-by*ax,length=(float)Math.sqrt(nx*nx+ny*ny+nz*nz);nx/=length;ny/=length;nz/=length;int face=1;float best=0;for(int f=0;f<6;f++){float dot=nx*PropulsionEmission.dx(f)+ny*PropulsionEmission.dy(f)+nz*PropulsionEmission.dz(f);if(dot>=0&&dot>best){best=dot;face=f;}}return face;}
 public static int objDirection(int[] data,int stride){float ax=Float.intBitsToFloat(data[stride*2])-Float.intBitsToFloat(data[0]),ay=Float.intBitsToFloat(data[stride*2+1])-Float.intBitsToFloat(data[1]),az=Float.intBitsToFloat(data[stride*2+2])-Float.intBitsToFloat(data[2]),bx=Float.intBitsToFloat(data[stride*3])-Float.intBitsToFloat(data[stride]),by=Float.intBitsToFloat(data[stride*3+1])-Float.intBitsToFloat(data[stride+1]),bz=Float.intBitsToFloat(data[stride*3+2])-Float.intBitsToFloat(data[stride+2]);float nx=ay*bz-az*by,ny=az*bx-ax*bz,nz=ax*by-ay*bx,inverse=(float)(1D/Math.sqrt(nx*nx+ny*ny+nz*nz));nx*=inverse;ny*=inverse;nz*=inverse;int face=2;float best=Float.MIN_VALUE;for(int f=0;f<6;f++){float dot=nx*PropulsionEmission.dx(f)+ny*PropulsionEmission.dy(f)+nz*PropulsionEmission.dz(f);if(dot>best){best=dot;face=f;}}return face;}
 public static int quad(int[] data,int x,int y,boolean rectangular){int stride=data.length/4;for(int v=0;v<4;v++)position(data,v*stride,x,y);int face=rectangular?direction(data,stride):objDirection(data,stride);if(rectangular){float[] lo={999,999,999},hi={-999,-999,-999};for(int v=0;v<4;v++)for(int a=0;a<3;a++){float n=Float.intBitsToFloat(data[v*stride+a]);if(n<lo[a])lo[a]=n;if(n>hi[a])hi[a]=n;}int[] original=data.clone();for(int v=0;v<4;v++){int corner=CORNERS[face][v],at=v*stride;float px=((corner&4)==0?lo:hi)[0],py=((corner&2)==0?lo:hi)[1],pz=((corner&1)==0?lo:hi)[2];for(int w=0;w<4;w++)if(Math.abs(px-Float.intBitsToFloat(original[w*stride]))<1e-5F&&Math.abs(py-Float.intBitsToFloat(original[w*stride+1]))<1e-5F&&Math.abs(pz-Float.intBitsToFloat(original[w*stride+2]))<1e-5F)System.arraycopy(original,w*stride,data,at,stride);data[at]=Float.floatToRawIntBits(px);data[at+1]=Float.floatToRawIntBits(py);data[at+2]=Float.floatToRawIntBits(pz);data[at+7]=(data[at+7]&0xff000000)|((PropulsionEmission.dx(face)*127)&255)|(((PropulsionEmission.dy(face)*127)&255)<<8)|(((PropulsionEmission.dz(face)*127)&255)<<16);}}else for(int v=0;v<4;v++){int at=v*stride,old=data[at+7];float a=(byte)old/127F,b=(byte)(old>>>8)/127F,c=(byte)(old>>>16)/127F,nx=component(x,y,0,a,b,c,false),ny=component(x,y,1,a,b,c,false),nz=component(x,y,2,a,b,c,false),length=(float)Math.sqrt(nx*nx+ny*ny+nz*nz);nx/=length;ny/=length;nz/=length;data[at+7]=(old&0xff000000)|(((byte)Math.round(nx*127F))&255)|((((byte)Math.round(ny*127F))&255)<<8)|((((byte)Math.round(nz*127F))&255)<<16); }return face;}
 public static void position(int[] data,int at,int x,int y){float a=Float.intBitsToFloat(data[at]),b=Float.intBitsToFloat(data[at+1]),c=Float.intBitsToFloat(data[at+2]);for(int axis=0;axis<3;axis++)data[at+axis]=Float.floatToRawIntBits(component(x,y,axis,a,b,c,true));}
}
